\label{g-t}
Let $\Omega$ be a bounded convex domain. Assume $x_0\in\Omega$ and $r>0$ to be such that $B_r(x_0)\subset\Omega$.  Then, there exists a constant $N=N(k,n)\geq1$  such that for any
solution $u$ to Equation~\eqref{6171} and any $0<T\leq 1$,
\begin{equation}\label{1127-6-c}
\begin{split}
\int_{\Omega} |u(x,T)|^2\,dx
&\leq  2\left(\int_{B_{r}(x_0)}\!\!\!|u(x,T)|^2\,dx\right)
^{\alpha(r)}\left(Ne^{\frac{R_\Omega^2}{2T}}\int_\Omega |u(x,0)|^2\,dx\right)^{1-\alpha(r)}\\
\end{split}
\end{equation}
with
\begin{equation*}
\alpha(r)=\frac{1}{1+\frac{32R_\Omega^2}{r^2}
e^{\frac{k^2}{\mu^*}}},
\end{equation*}
where $\mu^*:=(n-2)^2/4$ and $R_\Omega$ is the diameter of $\Omega$.\footnote{Note that $\mu^*$ is the best constant of the  Hardy inequality.}

\label{global}
Let $\Omega$ be a bounded domain with a $C^2$-smooth boundary, and let $\omega\subset\Omega$ be a non-empty open subset. Then, there are constants $N=N(\Omega,\omega,k,n)\geq 1$ and
$\alpha=\alpha(\Omega,\omega,k,n)$ with $\alpha\in(0,1)$ such that  for any
solution $u$ to Equation~\eqref{6171} and any $0<T\leq 1$,
\begin{equation}\label{cccc1}
\int_{\Omega}|u(x,T)|^2\;dx\leq
\left(\int_{\omega}|u(x,T)|^2\;dx\right)^{\alpha}
\left(Ne^{\frac{N}{T}}\int_{\Omega}|u(x,0)|^2\;dx\right)
^{1-\alpha}.
\end{equation}

\label{monotonicity}
Let $f\in L^2(\Omega\times(0,T))$, $u$ be a solution of
\eqref{coupled1} and $x_0\in\Omega$. Then the weighted frequency
function associated with $(u, f, x_0)$ has the following properties:

\noindent \textnormal{(i)}. For each $t\in(0,T]$ with $u(\cdot,t)\neq 0$ in
$L^2(\Omega)$,
\begin{equation*}
N_\lambda(t)=-\frac{1}{2}\frac{d}{dt}\log(H_\lambda(t))+
\frac{\int_{\Omega}ufG_{\lambda,x_0}\,dx}{\int_{\Omega}u^2G_{\lambda,x_0}
\,dx}\,.
\end{equation*}

\noindent \textnormal{(ii)}. When $\Omega$ is either convex or star-shaped
with respect to $x_0$,
\begin{equation*}
\frac{d}{dt}N_\lambda(t)\leq
\frac{N_\lambda(t)}{T-t+\lambda}+\frac{\int_{\Omega}f^2G_{\lambda,x_0}\,dx}
{H_\lambda(t)}\,
\end{equation*}
 for each $t\in(0,T]$ with $u(\cdot,t)\neq 0$ in
$L^2(\Omega)$.

By the Green formula, we have
\begin{equation*}
\begin{split}
\frac{d}{dt}H_\lambda(t)&=\int_\Omega2u\partial_tuG_{\lambda,x_0}+u^2\partial_tG_{\lambda,x_0}\,dx\\
&=2\int _\Omega u(\partial_tu-\Delta u)G_{\lambda,x_0}\,dx-2\int_\Omega|\nabla u|^2G_{\lambda,x_0}\,dx\\
&=2\int_\Omega ufG_{\lambda,x_0}\,dx-2I_\lambda(t),
\end{split}
\end{equation*}
which leads to  \textnormal{(i)}.\\

We now prove  \textnormal{(ii)}. By the integration by parts, it follows that
\begin{equation}\label{1117-1}
\begin{split}
\frac{d}{dt}H_\lambda(t)&=2\int_\Omega\Big(\partial_tu-\frac{\nabla u\cdot (x-x_0)}{2(T-t+\lambda)}-\frac{f}{2}\Big)uG_{\lambda,x_0}\,dx+
\int_\Omega fuG_{\lambda,x_0}\,dx,\\
\end{split}
\end{equation}

\begin{equation}\label{1117-2}
\begin{split}
I_\lambda(t)&=-\int_\Omega\Big(\partial_tu-\frac{\nabla u\cdot (x-x_0)}{2(T-t+\lambda)}-\frac{f}{2}\Big)uG_{\lambda,x_0}\,dx+
\frac{1}{2}\int_\Omega fuG_{\lambda,x_0}\,dx.\\
\end{split}
\end{equation}
Meanwhile,
\begin{equation}\label{1117-4}
\begin{split}
\frac{d}{dt}I_\lambda(t)&=2\int_\Omega \nabla u\cdot \nabla (\partial_tu)G_{\lambda,x_0}\,dx
+\int_\Omega\nabla(|\nabla u|^2)\cdot \nabla G_{\lambda,x_0}\,dx+\mathcal{A},\\
\end{split}
\end{equation}
where
\begin{equation*}\label{1117-3}
\mathcal{A}=\int_{\partial\Omega}\frac{(x-x_0)\cdot \nu_x}{2(T-t+\lambda)}
\left(\frac{\partial u}{\partial \nu}\right)^2G_{\lambda,x_0}\,d\sigma.
\end{equation*}
 Since
\begin{equation}\label{1117-6}
\begin{split}
\nabla(|\nabla u|^2)\cdot\nabla G_{\lambda,x_0}=\frac{-1}{T-t+\lambda}
\Big(\nabla u\cdot\nabla\big(\nabla u\cdot (x-x_0)\big)-
|\nabla u|^2\Big)G_{\lambda,x_0},
\end{split}
\end{equation}
it follows from \eqref{1117-4} and \eqref{1117-6} that
\begin{equation}\label{1117-8}
\begin{split}
\frac{d}{dt}I_\lambda(t)&=2\int_{\Omega}\nabla u\cdot\nabla\Big(\partial_t u-\frac{\nabla u\cdot(x-x_0)}{2(T-t+\lambda)}\Big)G_{\lambda,x_0}\,dx\\
&\;\;\;\;+\frac{I_\lambda(t)}{T-t+\lambda}+\mathcal{A}.
\end{split}
\end{equation}
On the other hand, we have by the Green formula,
\begin{equation}\label{1117-10}
\begin{split}
&\int_{\Omega}\nabla u\cdot\nabla\Big(\partial_t u-\frac{\nabla u\cdot (x-x_0)}{2(T-t+\lambda)}\Big)G_{\lambda,x_0}\,dx\\
&=-\mathcal{A}-\int_{\Omega}\Big(\partial_tu-\frac{\nabla u\cdot (x-x_0)}{2(T-t+\lambda)}\Big)\Big(\partial_tu-\frac{\nabla u\cdot (x-x_0)}{2(T-t+\lambda)}-f\Big)G_{\lambda,x_0}\,dx.\\
\end{split}
\end{equation}
From \eqref{1117-8} and \eqref{1117-10}, it holds that
\begin{equation}\label{1117-9}
\begin{split}
\frac{d}{dt}I_\lambda(t)&=-2\int_{\Omega}\Big(\partial_t u-\frac{\nabla u\cdot (x-x_0)}{2(T-t+\lambda)}-\frac{f}{2}\Big)^2G_{\lambda,x_0}\,dx+\frac{1}{2}
\int_\Omega f^2G_{\lambda,x_0}\,dx\\
&\;\;\;\;+\frac{I_\lambda(t)}{T-t+\lambda}-\mathcal{A}.
\end{split}
\end{equation}

Finally, we obtain from \eqref{1117-1}, \eqref{1117-2} and \eqref{1117-9} that
\begin{equation*}
\begin{split}
\frac{d}{dt}N_\lambda(t)&=\frac{\frac{d}{dt}\big(I_\lambda(t)\big)H_\lambda(t)
-I_\lambda(t)
\frac{d}{dt}H_\lambda(t)}{H^2_\lambda(t)}\\
&=\frac{N_\lambda(t)}{T-t+\lambda}+\frac{\int_\Omega f^2G_{\lambda,x_0}\,dx}{2H_\lambda(t)}-\frac{\mathcal{A}}
{H_\lambda(t)}-\frac{\Big(\int_\Omega fuG_{\lambda,x_0}\,dx\Big)^2}{2H_\lambda^2(t)}\\
&\;\;\;\;-\frac{2}{H_\lambda(t)}\int_\Omega \Big(
\partial_tu-\frac{\nabla u\cdot (x-x_0)}{2(T-t+\lambda)}-\frac{f}{2}\Big)^2G_{\lambda,x_0}\,dx\\
&\;\;\;\;+\frac{2}{H^2_\lambda(t)}\int_\Omega \Big(
\partial_tu-\frac{\nabla u\cdot (x-x_0)}{2(T-t+\lambda)}-\frac{f}{2}\Big)uG_{\lambda,x_0}\,dx.\\
\end{split}
\end{equation*}
Since $\Omega$ is either convex or star-shaped with respect to $x_0$,  it holds
that $(x-x_0)\cdot\nu_x\geq 0$ when $x\in\partial\Omega$ (see for instance  \cite[pp. 515]{evans}). (Here,
$\nu_x$ is the outward normalized vector of $\partial\Omega$ at $x$.)
Consequently, $\mathcal{A}\geq 0$. By the Cauchy-Schwartz
inequality,
\begin{multline*}
\left[\int_\Omega\Big(
\partial_t u-\frac{\nabla u\cdot (x-x_0)}{2(T-t+\lambda)}-\frac{f}{2}\Big)u G_{\lambda,x_0}\,dx\right]^2
\\
\leq \int_\Omega \Big(
\partial_t u-\frac{\nabla u\cdot (x-x_0)}{2(T-t+\lambda)}-\frac{f}{2}\Big)^2G_{\lambda,x_0}\,dx
\times
\int_\Omega u^2G_{\lambda,x_0}\,dx,
\end{multline*}
which leads to
\begin{equation*}
\frac{d}{dt}N_\lambda(t)\leq \frac{N_\lambda(t)}{T-t+\lambda}+\frac{\int_\Omega
f^2G_{\lambda,x_0}\,dx}{2H_\lambda(t)},
\end{equation*}
i.e.,  \textnormal{(ii)} stands.

\label{hardytype}
Let $x_0\in \Omega$ and $\mu^*:=(n-2)^2/4$, $n\geq3$. Then for each
$\lambda>0$ and each $\varphi\in H^1_0(\Omega)$, it holds that
\begin{equation}\label{pei3}
\begin{split}
\frac{1}{16\lambda^2}\int_{\Omega}|x-x_0|^2\varphi^2e^{-\frac{|x-x_0|^2}{4\lambda}}\,dx
\leq \int_{\Omega}\Big(|\nabla \varphi|^2-\frac{\mu^*}{|x|^2}\varphi^2\Big)e^{-\frac{|x-x_0|^2}{4\lambda}}\,dx\\
+\frac{n}{4\lambda} \int_{\Omega}\varphi^2e^{-\frac{|x-x_0|^2}{4\lambda}}\,dx.
\end{split}
\end{equation}

Recall the well-known Hardy inequality (cf., e.g., \cite{VZ}):
\begin{equation}\label{pei1}
\mu^*\int_{\Omega}\frac{g^2}{|x|^2}\,dx\leq \int_{\Omega}|\nabla
g|^2\,dx\;\;\mbox{for all}\; \; g\in H^1_0(\Omega).
\end{equation}
Given $\varphi\in H^1_0(\Omega)$, $\lambda>0$ and $x_0\in \Omega$,  let
$g=\varphi e^{-\frac{|x-x_0|^2}{8\lambda}}$. Clearly, $g\in H_0^1(\Omega)$ and
\begin{equation*}
\nabla g=\nabla \varphi e^{-\frac{|x-x_0|^2}{8\lambda}}-\frac{x-x_0}{4\lambda}
\varphi e^{-\frac{|x-x_0|^2}{8\lambda}}.
\end{equation*}
By \eqref{pei1},
\begin{equation*}\label{pei2}
\begin{split}
\mu^*\int_{\Omega}\frac{\varphi^2}{|x|^2}e^{-\frac{|x-x_0|^2}{4\lambda}}\,dx
&\leq \int_{\Omega}|\nabla \varphi|^2 e^{-\frac{|x-x_0|^2}{4\lambda}}
+\frac{|x-x_0|^2}{16\lambda^2}\varphi^2e^{-\frac{|x-x_0|^2}{4\lambda}}\,dx\\
&\;\;\;\;-\frac{1}{2\lambda}\int_{\Omega}(x-x_0)\cdot\nabla \varphi \varphi
e^{-\frac{|x-x_0|^2}{4\lambda}}\,dx.
\end{split}
\end{equation*}
By the integration  by  parts, we have
\begin{equation}\label{pei4}
\int_{\Omega}(x-x_0)\cdot\nabla \varphi \varphi
e^{-\frac{|x-x_0|^2}{4\lambda}}\,dx
=-\frac{1}{2}\int_{\Omega}\Big(n-\frac{|x-x_0|^2}{2\lambda}\Big)\varphi^2
e^{-\frac{|x-x_0|^2}{4\lambda}}\,dx.
\end{equation}
The last two inequalities imply \eqref{pei3}.

\label{morepei}
Let $x_0\in \Omega$ and $\mu^*$ be as above. Then for each
$m\geq0$ and each  $\gamma\in(0,2)$, there exists a constant
$C=C(m,\gamma)>0$ such that when $\lambda>0$ and $ \varphi\in
H_0^1(\Omega)$,
\begin{equation}\label{wang2.14}
\begin{split}
\frac{1}{16\lambda^2}\int_{\Omega}|x-x_0|^2
\varphi^2e^{-\frac{|x-x_0|^2}{4\lambda}}\,dx & \leq
\int_{\Omega}\Big[|\nabla
\varphi|^2-\frac{\mu^*}{|x|^2}\varphi^2-\frac{m}{|x|^\gamma}\varphi^2\Big]
e^{-\frac{|x-x_0|^2}{4\lambda}}\,dx\\
&\;\;\;\;+\Big[\frac{n}{4\lambda}+C\Big]\int_{\Omega}\varphi^2
e^{-\frac{|x-x_0|^2}{4\lambda}}\,dx.
\end{split}
\end{equation}

Given $x_0\in \Omega$,  $\lambda>0$ and $\varphi\in H^1_0(\Omega)$,
let $z=\varphi e^{-\frac{|x-x_0|^2}{8\lambda}}$. Then,
\begin{equation}\label{1551}
\nabla z=\nabla \varphi
e^{-\frac{|x-x_0|^2}{8\lambda}}-\frac{(x-x_0)}{4\lambda} \varphi
e^{-\frac{|x-x_0|^2}{8\lambda}}
\end{equation}
and
\begin{equation}\label{1552}
|\nabla z|^2=|\nabla \varphi|^2
e^{-\frac{|x-x_0|^2}{4\lambda}}+\frac{|x-x_0|^2}{16\lambda^2}\varphi^2
e^{-\frac{|x-x_0|^2}{4\lambda}} -\frac{(x-x_0)\cdot\nabla
\varphi}{2\lambda}\varphi e^{-\frac{|x-x_0|^2}{4\lambda}}.
\end{equation}
This, together with \eqref{pei4}, \eqref{1551}, \eqref{1552}, and the following improved version of Hardy inequality
(cf., for instance, \cite[(2.15)]{VZ})
\begin{equation*}
m\int_{\Omega}\frac{z^2}{|x|^\gamma}\,dx
\leq \int_{\Omega}\Big[|\nabla z|^2-\frac{\mu^*}{|x|^2}z^2\Big]\,dx
+C(m,\gamma)\int_{\Omega}z^2\,dx,\;\;\;\forall z\in H_0^1(\Omega),
\end{equation*}
leads to (\ref{wang2.14}).

\label{peiweightestimate}
Assume the bounded domain $\Omega$ is convex. Let $x_0\in\Omega$ and let $0<\lambda\leq T\leq 1$.
 Then for each $r>0$ with $B_r(x_0)\subset\Omega$ and each solution $u$ to Equation~\eqref{6171}, it holds that
\begin{multline}\label{pei0}
\int_{\Omega}|u(x,T)|^2e^{-\frac{|x-x_0|^2}{4\lambda}}\,dx
\leq \int_{B_r(x_0)}|u(x,T)|^2e^{-\frac{|x-x_0|^2}{4\lambda}}\,dx\\
+\frac{64\lambda}{r^2}e^{\frac{k^2}{\mu^*}}
\left[\log
\frac{\int_\Omega |u(x,0)|^2\,dx}{\int_\Omega |u(x,T)|^2\,dx}+
\mathcal{C}_1\right]
\int_{\Omega}|u(x,T)|^2
e^{-\frac{|x-x_0|^2}{4\lambda}}\,dx,
\end{multline}
where
\begin{equation*}\label{2911}
\mathcal{C}_1=\mathcal{C}_1(T,k,n,\mu^*,R_\Omega)=\frac{R_\Omega^2}{2T}+C(k)
+\frac{n}{4}\big(1+\frac{k^2}{\mu^*}\big)+n.
\end{equation*}

We only need to show the desired estimate \eqref{pei0} for an arbitrarily fixed solution  $u$  to
Equation \eqref{6171} with $u(\cdot, 0)\neq 0$ in $L^2(\Omega)$. Let
$N_\lambda(\cdot)$ be the weighted frequency function associated with $(u,
f, x_0)$  where $f=ku/|x|$. It follows from Lemma 2.5 in \cite{pw2}
that
\begin{multline}\label{pei5}
\int_\Omega|u(x,T)|^2
e^{-\frac{|x-x_0|^2}
{4\lambda}}\,dx\leq\int_{B_r(x_0)}|u(x,T)|^2e^{-\frac{|x-x_0|^2}{4\lambda}}\,dx
\\
+\frac{16\lambda}{r^2}
\Big[\lambda N_\lambda(T)+\frac n4\Big]
\int_\Omega|u(x,T)|^2
e^{-\frac{|x-x_0|^2}
{4\lambda}}\,dx.
\end{multline}

Next,
we apply Lemmas~\ref{monotonicity}, \ref{hardytype} and \ref{morepei} to deduce a bound for
the quantity $\lambda N_\lambda(T)$ when $0<\lambda\leq T\leq1$. Since $u(\cdot, 0)\neq 0$ in
$L^2(\Omega)$, by backward uniqueness it holds that $u(\cdot, t)\neq 0$ in $L^2(\Omega)$,
for each $t\in [0,T]$.
 From  (ii) of
Lemma~\ref{monotonicity} (where  $(u,f)=(u, ku/|x|)$), we have
\begin{equation}\label{Wang2.20}
\frac{d}{dt}N_\lambda(t)\leq \frac{N_\lambda(t)}{T-t+\lambda}
+\frac{k^2\int_{\Omega}\frac{u^2}{|x|^2}G_{\lambda,x_0}\,dx}{H_\lambda(t)}\;\;\;\mbox{for
each}\;\; t\in (0,T].
\end{equation}
By  Lemma~\ref{hardytype} (where $\varphi=u$ and $\lambda=T-t+\lambda$ with
$t\in (0,T]$), it follows that
\begin{equation*}
k^2\int_\Omega\frac{u^2}{|x|^2}G_{\lambda.x_0}dx\leq
\frac{k^2}{\mu^*}\int_\Omega |\nabla
u|^2G_{\lambda,x_0}dx+\frac{k^2n}{4\mu^*(T-t+\lambda)}\int_\Omega
u^2G_{\lambda,x_0}dx,\; t\in (0,T].
\end{equation*}
This, along with (\ref{Wang2.20}), indicates that
\begin{equation*}\label{21-2}
\frac{d}{dt}N_\lambda(t)\leq
\frac{N_\lambda(t)}{T-t+\lambda}+\frac{k^2}{\mu^*}
N_\lambda(t)+\frac{nk^2}{4\mu^*(T-t+\lambda)},\; t\in (0,T].
\end{equation*}
Consequently,
\begin{equation*}
\frac{d}{dt}\big[(T-t+\lambda)N_\lambda(t)\big]\leq
\frac{k^2}{\mu^*}(T-t+\lambda)N_\lambda(t)+\frac{nk^2}{4\mu^*}, \; t\in (0,T].
\end{equation*}
This yields
\begin{equation*}\label{295}
\frac{d}{dt}\Big[e^{-tk^2/\mu^*}(T-t+\lambda)N_\lambda(t)\Big]
\leq \frac{nk^2}{4\mu^*}e^{-tk^2/\mu^*},\;t\in(0,T].
\end{equation*}
Integrating the above inequality from $t$ to $T$, we get that
\begin{equation*}
e^{-Tk^2/\mu^*}\lambda N_\lambda(T)\leq e^{-tk^2/\mu^*}(T-t+\lambda)N_\lambda(t)
+\frac{nk^2}{4\mu^*}\int_t^Te^{-sk^2/\mu^*}\,ds,\,t\in(0,T].
\end{equation*}
Thus,
\begin{equation*}\label{297}
e^{-Tk^2/\mu^*}\lambda N_\lambda(T)\leq (T+\lambda)N_\lambda(t)
+\frac{nk^2}{4\mu^*},\,t\in(0,T].
\end{equation*}
Integrating  the above inequality with respect to $t$ over $(0,T/2)$, we obtain that
\begin{equation}\label{pei11}
e^{-Tk^2/\mu^*}\lambda N_\lambda(T)\leq \frac{2(T+\lambda)}{T}
\int_{0}^{T/2}N_\lambda(t)\,dt+\frac{nk^2}{4\mu^*}.
\end{equation}


On the other hand, by (i) of Lemma~\ref{monotonicity} (where $(u,f)=
(u,ku/|x|)$), we see  that
\begin{equation}\label{pei7}
N_\lambda(t)=-\frac{1}{2}\frac{d}{dt}\log \big(H_\lambda(t)\big)+\frac{\int_{\Omega}\frac{k}{|x|}u^2G_{\lambda,x_0}\,dx}
{H_\lambda(t)}.
\end{equation}
By Lemma~\ref{morepei} (where $\varphi=u$, $m=2|k|$, $\gamma=1$ and $\lambda=T-t+\lambda$), it stands that
\begin{equation*}\label{21-1}
2|k|\int_{\Omega}\frac{u^2}{|x|}
G_{\lambda,x_0}\,dx
\leq \int_{\Omega}|\nabla u|^2G_{\lambda,x_0}\,dx
+\Big[\frac{n}{4(T-t+\lambda)}+C(k)\Big]\int_{\Omega}u^2
G_{\lambda,x_0}\,dx.
\end{equation*}
This, along with \eqref{pei7}, implies that
\begin{equation*}
N_\lambda(t)\leq -\frac{d}{dt}\log \big(H_\lambda(t)\big)+
\Big[C(k)+\frac{n}{4(T-t+\lambda)}
\Big].
\end{equation*}

Integrating the above inequality over $(0,T/2)$, we get that
\begin{equation}\label{pei9}
\int_{0}^{T/2}N_\lambda(t)\,dt\leq\log \frac{H_\lambda(0)}{H_\lambda(T/2)}+\frac{T}{2}\Big[C(k)+\frac{n}{2T}
\Big].
\end{equation}
Notice that
\begin{equation*}\label{2913}
\begin{split}
\frac{H_\lambda(0)}{H_\lambda(T/2)}&=\frac{(T+\lambda)^{-n/2}\int_\Omega |u(x,0)|^2e^{-\frac{|x-x_0|^2}{4(T+\lambda)}}\,dx}
{(\frac{T}{2}+\lambda)^{- n/2}\int_\Omega |u(x,T/2)|^2e^{-\frac{|x-x_0|^2}{4(\frac{T}{2}+\lambda)}}\,dx}\\
&\leq e^{\frac{R_\Omega^2}{2T}}\frac{\int_\Omega |u(x,0)|^2\,dx}{\int_\Omega |u(x,T/2)|^2\,dx}.
\end{split}
\end{equation*}
From which and the standard  energy estimate
\begin{equation*}\label{2914}
\int_\Omega|u(x,T)|^2\,dx\leq
e^{C(k)T}\int_\Omega |u(x,T/2)|^2\,dx,
\end{equation*}
we have
\begin{equation}\label{pei10}
\frac{H_\lambda(0)}{H_\lambda(T/2)}\leq e^{\frac{R_\Omega^2}{2T}+C(k)}\frac{\int_\Omega |u(x,0)|^2\,dx}{\int_\Omega |u(x,T)|^2\,dx}.
\end{equation}
Therefore, it follows from \eqref{pei11}, \eqref{pei9} and  \eqref{pei10} that when $0<\lambda\leq T\leq1$
\begin{equation*}\label{pei12}
\begin{split}
\lambda N_\lambda(T)&\leq
4e^{\frac{k^2}{\mu^*}}
\left[\log \frac{\int_\Omega |u(x,0)|^2\,dx}{\int_\Omega |u(x,T)|^2\,dx}+
\frac{R_\Omega^2}{2T}+C(k)+\frac{n}{4}\big(1+\frac{k^2}
{\mu^*}\big)\right].
\end{split}
\end{equation*}
This, combined with \eqref{pei5}, arrives at the desired estimate
\eqref{pei0}.

Let us now choose
\begin{equation*}\label{1127-1-c}
\lambda_0=\frac{r^2}{128}e^{-\frac{k^2}{\mu^*}}
\left[\log \frac{\int_\Omega |u(x,0)|^2\,dx}{\int_\Omega |u(x,T)|^2\,dx}+\mathcal{C}_1\right]^{-1}
\end{equation*}
with the same constant $\mathcal C_1$ given in Lemma \ref{peiweightestimate}.
It is easy to check that  $0<\lambda_0<T$.
According to Lemma~\ref{peiweightestimate} (where $\lambda=\lambda_0$), it holds that
\begin{equation*}\label{1123-2-c}
\begin{split}
&\frac{1}{2}\int_\Omega|u(x,T)|^2
e^{-\frac{|x-x_0|^2}
{4\lambda_0}}\,dx
\leq\int_{B_r(x_0)}|u(x,T)|^2e^{-\frac{|x-x_0|^2}{4\lambda_0}}\,dx.\\
\end{split}
\end{equation*}
Which implies 
\begin{equation}\label{1117-20-c}
\int_\Omega|u(x,T)|^2\,dx\leq
2e^{\frac{R_\Omega^2}{4\lambda_0}}\int_{B_r(x_0)}\!\!|u(x,T)|^2\,dx.
\end{equation}
Notice that
\begin{equation*}
\begin{split}
e^{\frac{R_\Omega^2}{4\lambda_0}}&=e^{\frac{32R_\Omega^2e^{\frac{k^2}{\mu^*}}}{r^2}\left[\log \frac{\int_\Omega |u(x,0)|^2\,dx}{\int_\Omega |u(x,T)|^2\,dx}+\mathcal{C}_1\right]}=\left(e^{\mathcal{C}_1}
\frac{\int_\Omega |u(x,0)|^2\,dx}{\int_\Omega |u(x,T)|^2\,dx}\right)
^{\frac{32R_\Omega^2e^{\frac{k^2}{\mu^*}}}{r^2}}.
\end{split}
\end{equation*}
This, along with \eqref{1117-20-c}, leads to
\begin{equation*}
\begin{split}
&\int_\Omega|u(x,T)|^2
\,dx\leq 2\left(e^{\mathcal{C}_1}\frac{\int_\Omega |u(x,0)|^2\,dx}{\int_\Omega |u(x,T)|^2\,dx}\right)
^{\frac{32R_\Omega^2e^{\frac{k^2}{\mu^*}}
}{r^2}}\int_{B_r(x_0)}\!\!|u(x,T)|^2\,dx.
\end{split}
\end{equation*}
Which implies \eqref{1127-6-c} and completes the proof.

By following the argument in \cite{EFV} and the facts established above,  one can easily obtain  the following doubling property:  For any $u(\cdot,0)\in L^2(\Omega)$, there exists a constant $C$,  independent of $r$ and $x_0$, such that 
\begin{equation*}\label{1123-11-c}
\begin{split}
&\int_{B_{2r}(x_0)} |u(x,T)|^2\,dx\leq  C
\int_{B_r(x_0)}|u(x,T)|^2\,dx,  \\
\end{split}
\end{equation*}
for all $r>0$ such that $B_{2r}(x_0)\subset\Omega$. From which one can derive the space-like strong unique continuation property for solutions to \eqref{6171}.

\label{backwardenergyestimate}
Let $x_0\in\Omega$, $0<T\leq 1$, $R\in(0,1]$ and $\delta\in(0,1]$. Then
there exist constants $C(k)$ and $C_1(k)$ such that 
 for any solution $u$ of Equation \eqref{6171} with  $u(\cdot,0)=u_0\in L^2(\Omega)\setminus\{0\}$, 
\begin{equation}\label{ccan4}
\|u_0\|^2_{L^2(\Omega)}
\leq C(k)e^{\frac{1}{h_0}} \|u(\cdot,t)\|^2_{L^2(\Omega\cap B_{(1+\delta)R}(x_0))},\;\;\text{when}\;\;
t\in[T-h_0,T]
\end{equation}
with $h_0$ given by the equality
\begin{equation}\label{ch}
h_0=\frac{\delta^3R^2}{8(1+\delta)^2\log\Big[
\frac{C_1(k)}{\delta^2R^2}e^{\frac{1}{T}}\frac
{\|u_0\|^2_{L^2(\Omega)}}{\|u(\cdot,T)\|^2_{L^2(\Omega\cap B_R(x_0))}}\Big]}\,.
\end{equation}

We carry out the proof into three steps.\\

Step 1. Choose a suitable multiplier.\\

Let $\psi\in C^\infty_0(\Omega\cap B_{(1+\delta)R}(x_0))$ be the cut-off function verifying
\begin{equation*}
0\leq\psi\leq 1\;\text{in}\; \Omega\cap B_{(1+\delta)R}(x_0), \;\psi\equiv1 \;\text{in}\;\;\Omega\cap B_{(1+3\delta/4)R}(x_0) \;\;\text{and}\;\;|\nabla\psi|\leq \frac{C}{\delta R},
\end{equation*}
for some generic constant $ C\geq 1$ independent of $R$ and $\delta$.
For $h>0$ to be fixed later, multiplying by $e^{-\frac{|x-x_0|^2}{h}}\psi^2u$ the first equation
of Equation \eqref{6171} and integrating the latter over $\Omega\cap B_{(1+\delta)R}(x_0)$, we have
\begin{equation*}\label{s5}
\begin{split}
\frac{1}{2}\frac{d}{dt}\left(\int_{\Omega\cap B_{(1+\delta)R}(x_0)}|\psi u|^2 e^{-|x-x_0|^2/h}\,dx\right)&+\int_{\Omega\cap B_{(1+\delta)R}(x_0)}\nabla u\cdot \nabla (e^{-|x-x_0|^2/h}
\psi^2u)\,dx\\
&-\int_{\Omega\cap B_{(1+\delta)R}(x_0)}\frac{k}{|x|}
e^{-|x-x_0|^2/h}
|\psi u|^2\,dx=0.
\end{split}
\end{equation*}
From 
\begin{multline*}
\nabla (e^{-|x-x_0|^2/h}\psi^2u)=
\frac{-2(x-x_0)}{h}e^{-|x-x_0|^2/h}\psi^2u
+2e^{-|x-x_0|^2/h}\psi\nabla\psi u
+e^{-|x-x_0|^2/h}\psi^2\nabla u
\end{multline*}
and
\begin{equation*}
|\nabla(\psi u)|^2e^{-|x-x_0|^2/h}=
\psi^2|\nabla u|^2e^{-|x-x_0|^2/h}+|\nabla\psi|^2u^2e^{-|x-x_0|^2/h}
+2\psi u\nabla\psi\cdot\nabla ue^{-|x-x_0|^2/h},
\end{equation*}
it holds that
\begin{equation*}\label{ccan5}
\begin{split}
&\frac{1}{2}\frac{d}{dt}\left(\int_{\Omega\cap B_{(1+\delta)R}(x_0)}\!\!|\psi u|^2 e^{-\frac{|x-x_0|^2}{h}}
\,dx\right)
+\int_{\Omega\cap B_{(1+\delta)R}(x_0)}\!\!\Big[|\nabla(\psi u)|^2-\frac{k}{|x|}|\psi u|^2\Big]e^{-\frac{|x-x_0|^2}{h}}\,dx\\
&=\int_{\Omega\cap B_{(1+\delta)R}(x_0)}|\nabla \psi|^2u^2e^{-\frac{|x-x_0|^2}{h}}\,dx
+\frac{1}{h}\int_{\Omega\cap B_{(1+\delta)R}(x_0)}(x-x_0)\cdot
\big(\nabla(u^2)\big)\psi^2
e^{-\frac{|x-x_0|^2}{h}}\,dx.
\end{split}
\end{equation*}
By the integration by parts,
\begin{equation*}
\begin{split}
&\int_{\Omega\cap B_{(1+\delta)R}(x_0)}(x-x_0)\cdot\big(\nabla(u^2)\big)\psi^2
e^{-|x-x_0|^2/h}\,dx\\
&=-\int_{\Omega\cap B_{(1+\delta)R}(x_0)}\text{div}\big((x-x_0)\psi^2 e^{-|x-x_0|^2/h}\big)u^2\,dx\\
&=-\int_{\Omega\cap B_{(1+\delta)R}(x_0)}\!\!u^2\Big(n\psi^2 
+2\psi (x-x_0)\cdot\nabla\psi -\frac{2|x-x_0|^2}{h}\psi^2 \Big)e^{-\frac{|x-x_0|^2}{h}}\,dx\\
&=-n\int_{\Omega\cap B_{(1+\delta)R}(x_0)}|\psi u|^2 e^{-|x-x_0|^2/h}\,dx
-\int_{\Omega\cap B_{(1+\delta)R}(x_0)}2\psi u^2\nabla\psi\cdot (x-x_0) e^{-|x-x_0|^2/h}\,dx\\
&\;\;\;\;\;\;+
\frac{2}{h}\int_{\Omega\cap B_{(1+\delta)R}(x_0)}|x-x_0|^2\psi ue^{-|x-x_0|^2/h}\,dx.
\end{split}
\end{equation*}
Hence,
\begin{equation*}\label{ican5}
\begin{split}
&\frac{1}{2}\frac{d}{dt}\left(\int_{\Omega\cap B_{(1+\delta)R}(x_0)}\!\!|\psi u|^2 e^{-\frac{|x-x_0|^2}{h}}
\,dx\right)
+\int_{\Omega\cap B_{(1+\delta)R}(x_0)}\!\!\Big[|\nabla(\psi u)|^2-\frac{k}{|x|}|\psi u|^2\Big]e^{-\frac{|x-x_0|^2}{h}}\,dx\\
&\;\;=\int_{\Omega\cap B_{(1+\delta)R}(x_0)}|\nabla \psi|^2u^2e^{-|x-x_0|^2/h}\,dx-\frac{n}{h}\int_{\Omega\cap B_{(1+\delta)R}(x_0)}|\psi u|^2 e^{-|x-x_0|^2/h}\,dx\\
&\;\;\;\;\;\;-\frac{1}{h}\int_{\Omega\cap B_{(1+\delta)R}(x_0)}2\psi u^2\nabla\psi\cdot (x-x_0) e^{-|x-x_0|^2/h}\,dx\\
&\;\;\;\;\;\;+\frac{2}{h^2}\int_{\Omega\cap B_{(1+\delta)R}(x_0)}|x-x_0|^2|\psi u|e^{-|x-x_0|^2/h}\,dx\\
&\;\;\leq 2\int_{\Omega\cap B_{(1+\delta)R}(x_0)}|\nabla \psi|^2u^2e^{-|x-x_0|^2/h}\,dx-\frac{n}{h}\int_{\Omega\cap B_{(1+\delta)R}(x_0)}|\psi u|^2 e^{-|x-x_0|^2/h}\,dx\\
&\;\;\;\;\;+\frac{3}{h^2}\int_{\Omega\cap B_{(1+\delta)R}(x_0)}|x-x_0|^2|\psi u|^2e^{-|x-x_0|^2/h}\,dx.\\
\end{split}
\end{equation*}
By Lemma~\ref{morepei} (where $\varphi=\psi u$, $\lambda=h$ and $\gamma=1$), we have
\begin{equation*}
\begin{split}
&\int_{\Omega\cap B_{(1+\delta)R}(x_0)}\Big[|\nabla(\psi u)|^2-\frac{k}{|x|}|\psi u|^2\Big]e^{-|x-x_0|^2/h}\,dx\\
&\;\;\;\;\geq -\Big[\frac{n}{h}+C(k)\Big]\int_{\Omega\cap B_{(1+\delta)R}(x_0)}|\psi u|^2e^{-|x-x_0|^2/h}\,dx.
\end{split}
\end{equation*}
These last two inequalities indicate that
\begin{equation*}
\begin{split}
&\frac{1}{2}\frac{d}{dt}\left(\int_{\Omega\cap B_{(1+\delta)R}(x_0)}|\psi u|^2 e^{-|x-x_0|^2/h}
\,dx\right)
\leq \frac{3}{h^2}\int_{\Omega\cap B_{(1+\delta)R}(x_0)}|x-x_0|^2|\psi u|^2e^{-|x-x_0|^2/h}\,dx\\
&\;\;\;\;+2\int_{\Omega\cap B_{(1+\delta)R}(x_0)}|\nabla \psi|^2u^2e^{-|x-x_0|^2/h}\,dx
+C(k)\int_{\Omega\cap B_{(1+\delta)R}(x_0)}|\psi u|^2e^{-|x-x_0|^2/h}\,dx.
\end{split}
\end{equation*}
Which leads to 
\begin{equation}\label{ican6}
\begin{split}
&\frac{d}{dt}\left(\int_{\Omega\cap B_{(1+\delta)R}(x_0)}|\psi u|^2 e^{-|x-x_0|^2/h}
\,dx\right)\\
&\leq \Big[\frac{6(1+\delta)^2R^2}{h^2}+C(k)\Big]
\int_{\Omega\cap B_{(1+\delta)R}(x_0)}|\psi u|^2e^{-|x-x_0|^2/h}\,dx\\
&\;\;\;\;+\frac{C}{\delta^2R^2}
\int_{\Omega\cap (B_{(1+\delta)R}(x_0)\setminus B_{(1+\frac{3}{4}\delta)R}(x_0))}\!\!\!\!\!e^{-|x-x_0|^2/h}u^2\,dx.\\
\end{split}
\end{equation}

\bigskip

Step 2. Derive a localized energy estimate for $\int_{\Omega\cap B_R(x_0)}|u(x,T)|^2\,dx$.\\


For the simplicity of writing, we set
\begin{equation}\label{s7}
A=\frac{6(1+\delta)^2R^2}{h^2}+C(k),
\end{equation}
\begin{equation}\label{B}
B=\frac{C}{\delta^2R^2}e^{-\big(1+\frac{3}{4}\delta
\big)^2R^2/h},
\end{equation}
where $C(k)$ and $C$ are two constants in \eqref{ican6},
and
\begin{equation}\label{D}
D=\frac{\delta}{4(1+\delta)^2}.
\end{equation}
Clearly,
$$0<D< \frac{\delta}{8\delta}=\frac{1}{8}.$$
Therefore, by \eqref{ican6}, it holds that
\begin{multline*}
\frac{d}{dt}\Big(\int_{\Omega\cap B_{(1+\delta)R}(x_0)}|\psi u|^2 e^{-|x-x_0|^2/h}
\,dx\Big)\\
\leq  A\int_{\Omega\cap B_{(1+\delta)R}(x_0)}|\psi u|^2 e^{-|x-x_0|^2/h}\,dx
+Be^{C(k)}\|u_0\|_{L^2(\Omega)}^2.
\end{multline*}
Then, we have
\begin{equation*}\label{add2}
\begin{split}
\int_{\Omega\cap B_{(1+\delta)R}(x_0)}e^{-|x-x_0|^2/h}|\psi u(x,T)|^2\,dx
&\leq e^{A(T-t)}\int_{\Omega\cap B_{(1+\delta)R}(x_0)}e^{-|x-x_0|^2/h}|\psi u(x,t)|^2\,dx\\
&\;\;\;+e^{A(T-t)}Be^{C(k)}\|u_0\|_{L^2(\Omega)}^2.
\end{split}
\end{equation*}
Which  implies that when $T-Dh\leq t\leq T$,
\begin{equation*}
\begin{split}
\int_{\Omega\cap B_{(1+\delta)R}(x_0)}e^{-|x-x_0|^2/h}|\psi u(x,T)|^2\,dx
&\leq e^{ADh}\int_{\Omega\cap B_{(1+\delta)R}(x_0)}e^{-|x-x_0|^2/h}|\psi u(x,t)|^2\,dx\\
&\;\;\;+e^{ADh}Be^{C(k)}\|u_0\|_{L^2(\Omega)}^2.
\end{split}
\end{equation*}
Since $\psi(x)=1$ and $e^{-|x-x_0|^2/h}\geq e^{-R^2/h}$, $x\in \Omega\cap B_R(x_0)$, we have
\begin{equation}\label{ccan8}
\begin{split}
\int_{\Omega\cap B_{R}(x_0)}|u(x,T)|^2\,dx
&\leq e^{ADh+\frac{R^2}{h}}\int_{\Omega\cap B_{(1+\delta)R}(x_0)}e^{-|x-x_0|^2/h}| u(x,t)|^2\,dx\\
&\;\;\;+e^{ADh+\frac{R^2}{h}}Be^{C(k)}\|u_0\|_{L^2(\Omega)}^2.
\end{split}
\end{equation}
In view of \eqref{s7}, \eqref{B} and \eqref{D}, it holds that
\begin{equation}\label{ccan11}
\begin{split}
ADh+\frac{R^2}{h}&\leq\big(1+\frac{3\delta}{2}\big)\frac{R^2}{h}+C(k)
\end{split}
\end{equation}
and
\begin{equation}\label{10111}
\begin{split}
e^{ADh+\frac{R^2}{h}}Be^{C(k)}&\leq\frac{C_1(k)}{\delta^2R^2}
\exp\left\{\frac{R^2}{h}\Big[1+\frac{3\delta}{2}
-\big(1+\frac{3}{4}\delta\big)^2\Big]\right\},
\end{split}
\end{equation}
for some new constant $C_1(k)$.


\bigskip

Step 3. Fix  $h>0$.\\

By \eqref{10111}, we have
\begin{equation*}
e^{ADh+\frac{R^2}{h}}Be^{C(k)}\leq e^{-\frac{R^2}{h}\frac{9\delta^2}{16}
}\frac{C_1(k)}{\delta^2R^2}\leq e^{-\frac{\delta^2R^2}{2h}}
\frac{C_1(k)}{\delta^2R^2}.
\end{equation*}
This, along with \eqref{ccan8}, derives that the inequality
\begin{equation}\label{ccan9}
\begin{split}
\int_{\Omega\cap B_{R}(x_0)}|u(x,T)|^2\,dx
&\leq e^{ADh+\frac{R^2}{h}}
\int_{\Omega\cap B_{(1+\delta)R}(x_0)} |u(x,t)|^2\,dx\\
&\;\;+e^{-\frac{\delta^2R^2}{2h}}
\frac{C_1(k)}{\delta^2R^2}\|u_0\|_{L^2(\Omega)}^2,
\end{split}
\end{equation}
holds  when $T-Dh\leq t\leq T\leq1$.

Fix
\begin{equation*}
h=\frac{\delta^2R^2/2}{\log\Big[
\frac{C_1(k)}{\delta^2R^2}e^{\frac{1}{T}}\frac
{\|u_0\|^2_{L^2(\Omega)}}{\|u(\cdot,T)\|^2_{L^2(\Omega\cap B_R(x_0))}}\Big]},
\end{equation*}
to be such that
\begin{equation}\label{ccan10}
e^{-\frac{\delta^2R^2}{2h}}
\frac{C_1(k)}{\delta^2R^2}\|u_0\|_{L^2(\Omega)}^2=e^{-\frac{1}{T}}
\|u(\cdot,T)\|_{L^2(\Omega\cap B_R(x_0))}^2.
\end{equation}
Let $h_0=Dh$. Then $h_0$  satisfies
$h_0\in(0,T)$. Hence
it  follows from \eqref{D}, \eqref{ccan11} and  \eqref{ccan9}
that when $t\in[T-h_0,T]$,
\begin{equation}\label{valid}
\begin{split}
\big(1-e^{-\frac{1}{T}}\big)\|u(\cdot,T)\|^2_{L^2(\Omega\cap B_R(x_0))}
&\leq e^{ADh+\frac{R^2}{h}}\|u(\cdot,t)\|_{L^2(\Omega\cap B_{(1+\delta)R}(x_0))}^2\\
&\leq C(k)e^{\frac{R^2}{h}\big(1+\frac{3\delta}{2}\big)}
\|u(\cdot,t)\|_{L^2(\Omega\cap B_{(1+\delta)R}(x_0))}^2.
\end{split}
\end{equation}
 Because
\begin{equation*}
\begin{split}
&1-e^{-\frac{1}{T}}\geq \frac{1}{2}\,,\;\;\text{when}\;\;0<T\leq1,\\
&\frac{R^2}{h}\big(1+\frac{3\delta}{2}\big)
=\frac{DR^2}{h_0}\big(1+\frac{3\delta}{2}\big)< \frac{1}{h_0},
\end{split}
\end{equation*}
the desired estimate \eqref{ccan4} is valid from \eqref{valid} and \eqref{ccan10}.

\label{interpolation upto boundary}
Let $0<r<R\leq 1$  and $\delta\in(0,1]$. Suppose that
$B_r(x_0)\subset\Omega$ and $\Omega\cap B_{(1+2\delta)R}(x_0)$ is star-shaped
with center $x_0\in\Omega$. Then, there exist two constants
$N=N(\delta,R,k)\geq 1$ and $\theta=\theta(\delta,R,r,k)$ with $\theta\in (0,1)$,
such that  for any solution $u$  to Equation~(\ref{6171}) and any  $0<T\leq 1$,
\begin{equation}\label{interpolationi}
\int_{\Omega\cap B_R(x_0)}|u(x,T)|^2\;dx\leq
\left(Ne^{\frac{N}{T}}\int_{\Omega}|u(x,0)|^2\;dx\right)^{\theta}
\left(\int_{B_r(x_0)}|u(x,T)|^2\;dx\right)^{1-\theta}.
\end{equation}

We only need to prove the desired estimate \eqref{interpolationi} for an arbitrarily fixed solution  $u$  to
Equation \eqref{6171} with $u(\cdot, 0)\neq 0$ in $L^2(\Omega)$.
Let $\psi\in C_0^2(\Omega\cap B_{R+2\delta R}(x_0))$ be the cut-off function such that $0\leq\psi\leq1$,
$$\psi=1\;\;\text{in}\;\;\Omega\cap B_{R+\frac{3\delta}{2} R}(x_0),\;\;
|\nabla\psi|^2+|\Delta \psi|\leq\frac{C}{\delta^2R^2},$$
where the generic constant $C$ is independent of $R$ and $\delta$.
Let $z=\psi u$ and
\begin{equation}\label{2918}
f=\partial_tz-\Delta z=\frac{k}{|x|}z-2\nabla\psi\cdot\nabla u-\Delta\psi u.
\end{equation}
Associated with the triple $(z,f,x_0)$, we set for each $\lambda>0$ and  $t\in(0,T]$,
\begin{equation*}
H_\lambda(t)=\int_{\Omega\cap B_{(1+2\delta)R}(x_0)}z^2G_{\lambda,x_0}\,dx
\end{equation*}
and
\begin{equation*}
N_\lambda(t)=\frac{\int_{\Omega\cap B_{(1+2\delta)R}(x_0)}|\nabla z|^2G_{\lambda,x_0}\,dx}{\int_{\Omega\cap B_{(1+2\delta)R}(x_0)}z^2
G_{\lambda,x_0}\,dx}.
\end{equation*}


\bigskip

Step 1.
For each $t\in[T-D_1h_0,T]$, where $h_0$ is given by \eqref{ch} and  $0<D_1\leq 1$ is to be fixed later, we obtain
from Lemmas~\ref{hardytype}, \ref{morepei} and the similar argument as in Lemma~\ref{peiweightestimate}, as well as Lemma~\ref{backwardenergyestimate} (cf. \cite[Lemma 4, Step 1]{PWZ} ) that
\begin{equation}\label{21-4}
\frac{\int_{\Omega\cap B_{R+2\delta R}(x_0)}zfG_{\lambda,x_0}\,dx}
{\int_{\Omega\cap B_{R+2\delta R}(x_0)}z^2G_{\lambda,x_0}\,dx}
\leq \frac{1}{2}N_\lambda(t)
+\Big[\frac{n}{8(T-t+\lambda)}+C(2k)\Big]+
\frac{C}{\delta^2R^2}e^{-\frac{\delta^2 R^2}{D_1h_0+\lambda}}
\big(1+T^{-1/2}\big)e^{\frac{2}{h_0}}
\end{equation}
and
\begin{equation}\label{21-3}
\frac{\int_{\Omega\cap B_{R+2\delta R}(x_0)}f^2G_{\lambda,x_0}\,dx}
{\int_{\Omega\cap B_{R+2\delta R}(x_0)}z^2G_{\lambda,x_0}\,dx}
\leq \frac{3k^2}{\mu^*}
N_\lambda(t)+\frac{3nk^2}{4\mu^*(T-t+\lambda)}+
\frac{C}{\delta^4 R^2}e^{-\frac{\delta^2 R^2}{D_1h_0+\lambda}}
\big(1+T^{-1/2}\big)e^{\frac{2}{h_0}}.
\end{equation}

\bigskip

Step 2. It follows from  \cite[Lemma 2.5 ]{pw2}
that
\begin{align*}
&\int_{\Omega\cap B_{R+2\delta R}(x_0)}|z(x,T)|^2e^{-\frac{|x-x_0|^2}{4\lambda}}\,dx\\
&\leq \int_{B_{r}(x_0)}|u(x,T)|^2
e^{-\frac{|x-x_0|^2}{4\lambda}}\,dx
+\frac{16\lambda}{r^2}\Big[\lambda N_\lambda(T)+\frac{n}{4}\Big]
\int_{\Omega\cap B_{R+2\delta R}(x_0)}|z(x,T)|^2
e^{-\frac{|x-x_0|^2}{4\lambda}}\,dx.
\end{align*}



Step 3. By  \eqref{21-3} and (ii)  of Lemma~\ref{monotonicity}
(where $u=z$ and $f$ is given by \eqref{2918}), we have that for each $t\in[T-D_1h_0,T]$,
\begin{equation*}\label{21-2-2}
\frac{d}{dt}N_\lambda(t)\leq \frac{N_\lambda(t)}{T-t+\lambda}+\frac{3k^2}{\mu^*}
N_\lambda(t)+\frac{3nk^2}{4\mu^*(T-t+\lambda)}+
\frac{C}{\delta^4 R^2}e^{-\frac{\delta^2 R^2}{D_1h_0+\lambda}}
\big(1+T^{-1/2}\big)e^{\frac{2}{h_0}}.
\end{equation*}
Consequently,
\begin{equation*}
\frac{d}{dt}\big[(T-t+\lambda)N_\lambda(t)\big]\leq
\frac{3k^2}{\mu^*}(T-t+\lambda)N_\lambda(t)+\frac{3nk^2}{4\mu^*}
+\frac{C}{\delta^4 R^2}e^{-\frac{\delta^2 R^2}{D_1h_0+\lambda}}
\big(1+T^{-1/2}\big)e^{\frac{2}{h_0}}(T+\lambda).
\end{equation*}
It follows from the above inequality  that when $t\in[T-D_1h_0,T]$,
\begin{equation*}
\begin{split}
e^{-3Tk^2/\mu^*}\lambda N_\lambda(T)&\leq
(T-t+\lambda)N_\lambda(t)+\frac{3nk^2}{4\mu^*}
+\frac{C}{\delta^4 R^2}e^{-\frac{\delta^2 R^2}{D_1h_0+\lambda}}
\big(1+T^{-1/2}\big)e^{\frac{2}{h_0}}(T+\lambda).
\end{split}
\end{equation*}
Integrating  the above inequality with respect to $t$ over $[T-D_1h_0,T-D_1h_0/2]$, we obtain that
\begin{multline}\label{pei11-c}
e^{-3Tk^2/\mu^*}\lambda N_\lambda(T)\leq \frac{2(D_1h_0+\lambda)}{D_1h_0}
\int_{T-D_1h_0}^{T-D_1h_0/2}N_\lambda(t)\,dt\\+
\frac{3nk^2}{4\mu^*}+\frac{C}{\delta^4 R^2}e^{-\frac{\delta^2 R^2}{D_1h_0+\lambda}}
\big(1+T^{-1/2}\big)e^{\frac{2}{h_0}}(T+\lambda).
\end{multline}
On the other hand, we see from \eqref{21-4} and  (i) in Lemma~\ref{monotonicity} (where $u=z$ and $f$ is given by \eqref{2918}) that
\begin{equation*}
N_\lambda(t)\leq -\frac{d}{dt}\log \big(H_\lambda(t)\big)+
\Big[C(2k)+\frac{n}{4(T-t+\lambda)}
\Big]+\frac{C}{\delta^2}e^{-\frac{\delta^2 R^2}{D_1h_0+\lambda}}
\big(1+T^{-1/2}\big)e^{\frac{2}{h_0}}.
\end{equation*}

Integrating the above inequality over $[T-D_1h_0,T-D_1h_0/2]$, we get that
\begin{equation}\label{pei9-c}
\int_{T-D_1h_0}^{T-D_1h_0/2}N_\lambda(t)\,dt\leq\log \frac{H_\lambda(T-D_1h_0)}{H_\lambda(T-D_1h_0/2)}+\frac{T}{2}\Big[C(k)+\frac{n}{2T}
\Big]+
\frac{C}{\delta^2}e^{-\frac{\delta^2 R^2}{D_1h_0+\lambda}}
\big(1+T^{-1/2}\big)e^{\frac{2}{h_0}}.
\end{equation}
Notice from Lemma~\ref{backwardenergyestimate} that
\begin{equation}\label{pei10-c}
\frac{H_\lambda(T-D_1h_0)}{H_\lambda(T-D_1h_0/2)}\leq e^{C(k)+\frac{(R+\delta R)^2}{2D_1h_0}+\frac{2}{h_0}}.
\end{equation}
Therefore, it follows from \eqref{pei11-c}, \eqref{pei9-c} and  \eqref{pei10-c} that when $0<\lambda\leq D_1h_0$,
\begin{equation*}\label{pei12-c}
\begin{split}
\lambda N_\lambda(T)&\leq
4e^{\frac{3k^2}{\mu^*}}
\left[\frac{(R+\delta R)^2}{2D_1h_0}+\frac{2}{h_0}+C(k)+\frac{n}{2}\big(
1+\frac{3k^2}{\mu^*}\big)+\mathcal{M}\right]
\end{split}
\end{equation*}
with
$$\mathcal{M}=\frac{C}{\delta^4 R^2}e^{-\frac{\delta^2 R^2}{D_1h_0+\lambda}}
\big(1+T^{-1/2}\big)e^{\frac{2}{h_0}}
+\frac{C}{\delta^2}e^{-\frac{\delta^2 R^2}{D_1h_0+\lambda}}
\big(1+T^{-1/2}\big)e^{\frac{2}{h_0}}.$$


\bigskip

Step 4. Let
$$D_1=\delta^2 R^2\;\;\;\text{and}\;\;\lambda=\varepsilon D_1h_0.$$
Here $\varepsilon\in(0,1)$ will be choose later.
Then
\begin{equation*}
\frac{2}{h_0}-\frac{\delta^2 R^2}{D_1h_0+\lambda}
\leq 0,
\end{equation*}
and consequently
\begin{equation*}
\mathcal M\leq \frac{C}{\delta^4 R^2}\big(1+T^{-1/2}\big).
\end{equation*}
Therefore, by Step 4 and noticing that $0<h_0<T\leq1$, we have
\begin{eqnarray*}
\frac{16\lambda}{r^2}\Big[\lambda N_\lambda(T)+\frac{n}{4}\Big]
&\leq& \frac{\varepsilon D_1}{r^2}e^{\frac{3k^2}{\mu^*}}
\Big[C(\mu^*,k,n)h_0+D_1h_0 \frac{C}{\delta^4R^2}\big(1+T^{-1/2}\big)
+\frac{(R+\delta R)^2}{2D_1}
\Big]\\
&\leq&\varepsilon C(\delta,R,r,k,\mu^*).
\end{eqnarray*}

\bigskip

Step 5. Finally, we choose $\varepsilon\in(0,1)$, which is independent of $T$, such that
\begin{align*}
\frac{16\lambda}{r^2}\Big[\lambda N_\lambda(T)+\frac{n}{4}\Big]\leq
 \varepsilon C(\delta,R,r,k,\mu^*)=\frac{1}{2}.
\end{align*}
Hence, by Step 2, we get that
\begin{align*}
\int_{\Omega\cap B_{R+2\delta R}(x_0)}|z(x,T)|^2e^{-\frac{|x-x_0|^2}
{4\lambda}}\,dx
\leq 2\int_{B_{r}(x_0)}|u(x,T)|^2e^{-\frac{|x-x_0|^2}{4\lambda}}\,dx,
\end{align*}
which implies that
\begin{align}\label{dudu}
\int_{\Omega\cap B_{R}(x_0)}|u(x,T)|^2\,dx
\leq e^{\frac{R^2}{4\lambda}}
\int_{B_{r}(x_0)}|u(x,T)|^2\,dx.
\end{align}
Recall that
$$\lambda=\varepsilon D_1 h_0=
\frac{C(r,R,\delta,k,\mu^*)}{
\log\Big[\frac{C}{\delta^2 R^2}e^{\frac{1}{T}}\frac{\|u(\cdot,0)\|^2_{L^2(\Omega)}}{\|u(\cdot,T)\|
^2_{L^2(\Omega\cap B_R(x_0))}}\Big]}\;.
$$
Thereby,
$$e^{\frac{R^2}{4\lambda}}=
\Big[\frac{C}{\delta^2 R^2}e^{\frac{1}{T}}\frac{\|u(\cdot,0)\|^2_{L^2(\Omega)}}{\|u(\cdot,T)\|
^2_{L^2(\Omega\cap B_R(x_0))}}\Big]^{C(r,R,\delta,k,\mu^*)}.
$$
Which, together with \eqref{dudu},  completes the proof.

Firstly, by Lemma~\ref{interpolation upto boundary}  and
constructing a sequence of balls chained along a curve, we claim that, for any compact sets $K_1$ and $K_2$
with non-empty interior in $\Omega$, there are constants
$N_1=N_1(K_1,K_2,k,n)\geq 1$ and $\alpha_1=\alpha_1(K_1,K_2,k,n)\in(0,1)$
such that
\begin{equation}\label{interior}
\int_{K_1}|u(x,T)|^2\;dx\leq \left(N_1e^{\frac{N_1}{T}}
\int_{\Omega}|u(x,0)|^2\;dx\right)^{1-\alpha_1}
\left(\int_{K_2}|u(x,T)|^2\;dx\right)^{\alpha_1}.
\end{equation}
Indeed, let
\begin{equation}\label{covering}
K_1\subset\bigcup_{i=1}^{p}B_{r}(x_i)\subset\Omega, \;\;\;\;
B_{r}(x_0)\subset K_2,
\end{equation}
and for each $B_{r}(x_i)$ with $1\leq i\leq p$, there exists a chain
of balls $B_{r}(x_i^j)$, $1\leq j\leq n_i$, such that
\begin{equation}\label{chain}
\begin{split}
&B_r(x_i^{1})=B_{r}(x_i),\;\;B_r(x_i^{n_i})=B_{r}(x_0),\\
&B_{r}(x_i^j)\subset B_{2r}(x_i^{j+1})\subset\Omega,\;\;1\leq j\leq
n_i-1,
\end{split}
\end{equation}
where $0<r=r(\Omega,K_1,K_2)<1/2$ is a constant. By
Lemma~\ref{interpolation upto boundary},  we get that there are
$N_i^j= N_i^j(r,k,n)\geq 1$ and $\theta_i^j=\theta_i^j(r,k,n)\in(0,1)$ such
that
\begin{equation*}
\int_{B_{2r}(x_i^{j+1})}|u(x,T)|^2\;dx\leq
\left(N_i^je^{\frac{N_i^j}{T}}\int_{\Omega}|u(x,0)|^2\;dx\right)
^{\theta_i^j}
\left(\int_{B_r(x_i^{j+1})}|u(x,T)|^2\;dx\right)^{1-\theta_i^j}.
\end{equation*}
This, together with \eqref{chain}, implies that there are
$N_i=N_i(K_1,K_2,k,n)\geq 1$ and $\theta_i=\theta_i(K_1,K_2,k,n)\in(0,1)$
such that
\begin{equation*}
\int_{B_{r}(x_i)}|u(x,T)|^2\;dx\leq
\left(N_ie^{\frac{N_i}{T}}\int_{\Omega}|u(x,0)|^2\;dx\right)
^{\theta_i} \left(\int_{B_r(x_0)}|u(x,T)|^2\;dx\right)^{1-\theta_i}.
\end{equation*}
This, along with (\ref{covering}) leads to the estimate \eqref{interior}.


Secondly, since $\partial\Omega$ is of class $C^2$,  there are a
finite set $ \Lambda\subset \Omega$, $0<\delta<1$ and a family of
positive numbers $0<r_x\le 1$, $x\in\Lambda$, such that
\begin{equation*}
\partial\Omega\subset \bigcup_{x\in \Lambda} B_{r_x}(x)\;\;\;\mbox{and}\;\;\; B_{\left(1+2\delta\right)r_x}(x)\cap\Omega\ \text{is}\ \text{star-shaped with center}\;x.
\end{equation*}
Then we apply Lemma~\ref{interpolation upto boundary} with
$\Omega\cap B_{(1+2\delta)r_x}(x),x\in\Lambda$, and the same
arguments as above to get that, when $\Gamma$ is a neighborhood of
$\partial\Omega$ and $K_3$ is a compact set with non-empty interior
in $\Omega$, there are constants $N_2=N_2(\Gamma,K_3,k,n)\geq 1$ and
$\alpha_2=\alpha_2(\Gamma,K_3,k,n)\in(0,1)$ such that
\begin{equation*}
\int_{\Gamma}|u(x,T)|^2\;dx\leq \left(N_2e^{\frac{N_2}{T}}
\int_{\Omega}|u(x,0)|^2\;dx\right)^{1-\alpha_2}
\left(\int_{K_3}|u(x,T)|^2\;dx\right)^{\alpha_2}.
\end{equation*}

Finally, we derive the desire estimate \eqref{cccc1} from the
previous two statements with $\Omega\subset(\Gamma\cup K_1)$ and
$(K_2\cup K_3)\subset\omega$.
